// Router: nhan Message Envelope (spec ARCHITECTURE.md muc 3) tu Gateway.
// Ban REVAMP (05/09/2026): bo han view_file (OneDrive) va /sync - tam thoi tat, se lam sau.
// Chi con: help / task / chitiet / taotask (placeholder) / free_text.
const items = $input.all();

function parseCommand(rawText) {
  let command = '';
  let params = '';
  if ((rawText || '').startsWith('/')) {
    const parts = rawText.trim().split(/\s+/);
    command = parts[0].toLowerCase();
    params = parts.slice(1).join(' ');
  } else {
    params = rawText || '';
  }
  return { command, params };
}

function computeRoute(command, params) {
  if (params.startsWith('chitiet_')) {
    return { route: 'chitiet', params: 'chitiet', taskId: params.replace('chitiet_', '').trim() };
  }
  // /sync dung DEEP-LINK dang text (nhu chitiet_), KHONG dung inline keyboard callback - on dinh hon.
  // Deep-link Telegram chi cho phep [A-Za-z0-9_-], khong dung duoc dau ":" nen dung "_" lam phan cach.
  if (params.startsWith('sync_folder_')) {
    return { route: 'sync_folder', params: params.replace('sync_folder_', '').trim(), taskId: null };
  }
  if (params.startsWith('sync_list_')) {
    return { route: 'sync_list', params: params.replace('sync_list_', '').trim(), taskId: null };
  }
  if (params.startsWith('sync_now_')) {
    return { route: 'sync_now', params: params.replace('sync_now_', '').trim(), taskId: null };
  }
  if (params === 'sync_later') {
    return { route: 'sync_later', params: '', taskId: null };
  }
  // Deep-link cho /help hyperlink (lenh khong can tham so, bam thang khong can go tay)
  if (params === 'menu_sync') return { route: 'sync', params: '', taskId: null };
  if (params === 'menu_sync_status') return { route: 'sync_status', params: '', taskId: null };
  if (params === 'menu_db_status') return { route: 'db_status', params: '', taskId: null };
  if (command === '/task') return { route: 'task', params, taskId: null };
  if (command === '/help' || command === '/start') return { route: 'help', params, taskId: null };
  if (command === '/sync') return { route: 'sync', params, taskId: null };
  if (command === '/sync_status') return { route: 'sync_status', params, taskId: null };
  if (command === '/db_status') return { route: 'db_status', params, taskId: null };
  if (!command && params) return { route: 'free_text', params, taskId: null };
  return { route: 'unknown_command', params, taskId: null };
}

return items.map(it => {
  const env = it.json ?? {};
  const isCallback = env.kind === 'callback';
  const rawText = isCallback ? (env.callback?.data || '') : (env.text || '');

  let route, command = '', params = '', taskId = null;

  if (isCallback) {
    if (rawText.startsWith('chitiet_')) {
      route = 'chitiet'; taskId = rawText.replace('chitiet_', '').trim(); params = 'chitiet';
    } else {
      route = 'unknown_command'; params = rawText;
    }
  } else {
    const parsed = parseCommand(rawText);
    command = parsed.command;
    const r = computeRoute(parsed.command, parsed.params);
    route = r.route; params = r.params; taskId = r.taskId;
  }

  const legacyMessage = !isCallback ? {
    text: env.text || '',
    chat: { id: env.chat_id },
    message_id: env.raw?.message_id ?? null,
    from: { id: env.user_id, username: env.username }
  } : undefined;
  const legacyCallback = isCallback ? {
    id: env.callback?.id,
    data: env.callback?.data,
    message: { chat: { id: env.chat_id }, message_id: env.callback?.message_id }
  } : undefined;

  return {
    json: {
      route, command, params, taskId,
      chatId: env.chat_id,
      messageId: isCallback ? (env.callback?.message_id ?? null) : (env.raw?.message_id ?? null),
      isCallback,
      originalData: { ...env, message: legacyMessage, callback_query: legacyCallback }
    }
  };
});

const input = $json;
const botUsername = $('⚙️ Config').first().json.botUsername;
const linkSync = `https://t.me/${botUsername}?start=menu_sync`;
const linkSyncStatus = `https://t.me/${botUsername}?start=menu_sync_status`;
const linkDbStatus = `https://t.me/${botUsername}?start=menu_db_status`;

const helpText = `<b>\U0001F4D8 Danh sach lenh Telegram</b>\n\n` +
  `\U0001F449 <code>/task &lt;tu khoa&gt;</code> - Tim task\n` +
  `\U0001F449 <code>/task chitiet_&lt;id&gt;</code> - Chi tiet task\n\n` +
  `\U0001F4CB <a href="${linkSync}">/sync</a> - Chon Folder/List de dong bo (chi admin)\n` +
  `\U0001F4CB <a href="${linkSyncStatus}">/sync_status</a> - Xem cac List se duoc tu dong dong bo\n` +
  `\U0001F4CA <a href="${linkDbStatus}">/db_status</a> - Thong ke du lieu hien co trong he thong\n\n` +
  `\U0001F4CC <i>Vi du:</i>\n<code>/task linh nhi</code>`;
return [{ json: { ...input, text: helpText, parse_mode: "HTML" } }];

const raw = ($json.params || '').trim();
const normalize = (s) => (s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/\u0111/g, 'd').replace(/\u0110/g, 'D').toLowerCase();
return [{ json: { ...$json, originalText: raw, originalText_khong_dau: normalize(raw) } }];

const chatId = $('Phân tích lệnh').first().json.chatId;
const searchText = $('Prepare Search').first().json.originalText || '';
const all = $input.all().map(i => i.json).filter(t => t && t.id); // loc bo item rong (alwaysOutputData placeholder)

const escapeHtml = (t) => (t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cleanLink = (l) => (l || '').replace(/^'+|'+$/g, '').replace(/[{}]/g, '').trim();
const botUsername = $('⚙️ Config').first().json.botUsername;

if (all.length === 0) {
  return [{ json: { chatId,
    text: `❌ Không tìm thấy kết quả nào phù hợp với từ khóa <b>${escapeHtml(searchText)}</b>`,
    parse_mode: "HTML" } }];
}

const formatTask = (task, index) => {
  const link = `https://t.me/${botUsername}?start=chitiet_${task.id}`;
  const onedrive = task.onedrive_link ? cleanLink(task.onedrive_link) : '';
  const clickupUrl = task.url ? cleanLink(task.url) : '';
  return (
`<b>${index + 1}.</b> <a href="${link}">${escapeHtml(task.name)}</a>
├ Trạng thái: ${escapeHtml(task.status) || 'Không rõ'}
├ List: ${task.list_name ? escapeHtml(task.list_name) : 'Không rõ'}
${onedrive ? `├ 📁 <a href="${onedrive}">Xem OneDrive</a>\n` : ''}└ 🔗 <a href="${clickupUrl}">Xem trong ClickUp</a>`
  );
};

// total_count lay tu COUNT(*) OVER() trong query - la con so CHINH XAC, khong bi anh huong boi LIMIT
const totalCount = all.length > 0 ? Number(all[0].total_count) : 0;
const shown = all; // da gioi han LIMIT 10 san trong query
const hasMore = totalCount > shown.length;

const header = hasMore
  ? `🔍 <b>Kết quả tìm kiếm: ${escapeHtml(searchText)}</b>\nTìm thấy <b>${totalCount}</b> kết quả phù hợp, hiển thị ${shown.length} kết quả gần đúng nhất:`
  : `🔍 <b>Kết quả tìm kiếm: ${escapeHtml(searchText)}</b>\nTìm thấy ${totalCount} kết quả:`;

const lines = [header];
shown.forEach((task, i) => lines.push(formatTask(task, i)));
if (hasMore) {
  lines.push(`💡 Còn ${totalCount - shown.length} kết quả khác chưa hiển thị — vui lòng nhập từ khóa cụ thể hơn để thu hẹp kết quả.`);
}

return [{ json: { chatId, text: lines.join('\n\n'), parse_mode: "HTML" } }];

const chatId = $('Phân tích lệnh').first().json.chatId;
const taskRows = $('task_detail_sql').all().map(i => i.json).filter(t => t && t.id);
const linkRows = $input.all().map(i => i.json).filter(r => r && r.order_task_id);
const escapeHtml = (t) => (t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cleanLink = (l) => (l || '').replace(/^'+|'+$/g, '').replace(/[{}]/g, '').trim();
const botUsername = $('⚙️ Config').first().json.botUsername;

if (taskRows.length === 0) {
  return [{ json: { chatId, text: '❌ Không tìm thấy task này.', parse_mode: 'HTML' } }];
}
const task = taskRows[0];
const lines = [];
lines.push(`<b>${escapeHtml(task.name)}</b>`);
lines.push(`├ Mô tả: ${escapeHtml(task.description?.trim()) || 'Không rõ'}`);
lines.push(`├ Trạng thái: ${escapeHtml(task.status) || 'Không rõ'}`);
lines.push(`├ List: ${task.list_name ? escapeHtml(task.list_name) : 'Không rõ'}`);
if (task.phu_trach) lines.push(`├ Phụ trách: ${escapeHtml(task.phu_trach)}`);
if (task.onedrive_link) {
  // Chi hien link phang - tinh nang "Xem file" (Graph API, liet ke tung file) TAM TAT theo yeu cau,
  // se lam lai o phien ban sau.
  lines.push(`├ 📁 <a href="${cleanLink(task.onedrive_link)}">Xem OneDrive</a>`);
}

// Y tuong #3: thong ke + link toi cac task Don Hang lien quan qua DKPV/PVTC
const dkpvLinks = linkRows.filter(r => r.link_type === 'dkpv');
const pvtcByYear = {};
linkRows.filter(r => r.link_type === 'pvtc').forEach(r => {
  const y = r.pvtc_year || 'khac';
  if (!pvtcByYear[y]) pvtcByYear[y] = [];
  pvtcByYear[y].push(r);
});

if (dkpvLinks.length > 0) {
  lines.push(`├ 📝 Đăng ký phỏng vấn (DKPV): <b>${dkpvLinks.length}</b> đơn hàng`);
  dkpvLinks.forEach(r => {
    const link = `https://t.me/${botUsername}?start=chitiet_${r.order_task_id}`;
    lines.push(`│   • <a href="${link}">${escapeHtml(r.order_task_name)}</a> (${escapeHtml(r.order_task_status) || 'không rõ'})`);
  });
}
for (const [year, rows] of Object.entries(pvtcByYear)) {
  lines.push(`├ ✅ Được nhận (PVTC ${year}): <b>${rows.length}</b> đơn hàng`);
  rows.forEach(r => {
    const link = `https://t.me/${botUsername}?start=chitiet_${r.order_task_id}`;
    lines.push(`│   • <a href="${link}">${escapeHtml(r.order_task_name)}</a> (${escapeHtml(r.order_task_status) || 'không rõ'})`);
  });
}

lines.push(`└ 🔗 <a href="${cleanLink(task.url)}">Xem trong ClickUp</a>`);

return [{ json: { chatId, text: lines.join('\n'), parse_mode: 'HTML' } }];

// File nay CHI danh cho System Bot (admin control panel), khong dung switch DEV/PROD nua.
const config = {
  botUsername: 'elite_n8n_system_bot',
  ADMIN_CHAT_ID: '975005174', // dung chung voi Gateway/Live Update - doi neu can
};

return [{ json: { ...$json, ...config } }];

const botUsername = $('⚙️ Config').first().json.botUsername;
const chatId = $('Phân tích lệnh').first().json.chatId;
const folders = $input.all().map(i => i.json);
const escapeHtml = (t) => (t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

if (folders.length === 0) {
  return [{ json: { chatId, text: '⚠️ Không tìm thấy Folder nào trong Space.', parse_mode: 'HTML' } }];
}

const lines = ['📁 <b>Chọn Folder muốn đồng bộ:</b>'];
folders.forEach((f, i) => {
  const link = `https://t.me/${botUsername}?start=sync_folder_${f.id}`;
  lines.push(`${i + 1}. <a href="${link}">${escapeHtml(f.name)}</a>`);
});
return [{ json: { chatId, text: lines.join('\n'), parse_mode: 'HTML' } }];

const botUsername = $('⚙️ Config').first().json.botUsername;
const chatId = $('Phân tích lệnh').first().json.chatId;
const folderId = $('Phân tích lệnh').first().json.params;
const lists = $input.all().map(i => i.json);
const escapeHtml = (t) => (t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

if (lists.length === 0) {
  return [{ json: { chatId, text: '⚠️ Folder này không có List nào.', parse_mode: 'HTML' } }];
}

const lines = ['📋 <b>Chọn List muốn đồng bộ:</b>'];
lists.forEach((l, i) => {
  const link = `https://t.me/${botUsername}?start=sync_list_${l.id}_${folderId}`;
  lines.push(`${i + 1}. <a href="${link}">${escapeHtml(l.name)}</a>`);
});
return [{ json: { chatId, text: lines.join('\n'), parse_mode: 'HTML' } }];

const raw = $('Phân tích lệnh').first().json.params;
const [listId, folderId] = raw.split('_'); // doi tu ':' sang '_' (deep-link khong cho phep ':')
return [{ json: { listId, folderId } }];

const info = $('Tách List ID + Folder ID').first().json;
const listData = $('ClickUp - Get List Info').first().json;
return [{
  json: {
    list_id: info.listId,
    list_name: listData.name || '',
    folder_id: info.folderId,
    folder_name: listData.folder?.name || '',
    added_by: String($('Phân tích lệnh').first().json.chatId),
  }
}];

const t = $json;
const chatId = $('Phân tích lệnh').first().json.chatId;
const botUsername = $('⚙️ Config').first().json.botUsername;

const syncNowLink = `https://t.me/${botUsername}?start=sync_now_${t.list_id}`;
const syncLaterLink = `https://t.me/${botUsername}?start=sync_later`;

const text = `✅ Đã lưu List "<b>${t.list_name}</b>" vào danh sách tự động đồng bộ (mỗi 5 ngày).\n\n` +
  `Đồng bộ ngay bây giờ luôn không?\n` +
  `👉 <a href="${syncNowLink}">⚡ Đồng bộ ngay</a>\n` +
  `👉 <a href="${syncLaterLink}">⏳ Chờ lần sau</a>`;

return [{ json: { chatId, text, parse_mode: 'HTML' } }];

const chatId = $('Phân tích lệnh').first().json.chatId;
const rows = $input.all().map(i => i.json).filter(r => r && r.list_id);
const escapeHtml = (t) => (t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

if (rows.length === 0) {
  return [{ json: { chatId,
    text: '📋 <b>Chưa có List nào được đăng ký để tự động đồng bộ.</b>\nLần Schedule tiếp theo sẽ dùng List mặc định trong Config.\n\n💡 Dùng lệnh /sync để chọn List cần đồng bộ.',
    parse_mode: 'HTML' } }];
}

const lines = [`📋 <b>Danh sách List sẽ được tự động đồng bộ (mỗi 5 ngày):</b>\n`];
rows.forEach((r, i) => {
  const addedDate = r.added_at ? new Date(r.added_at).toLocaleString('vi-VN') : 'không rõ';
  lines.push(`${i + 1}. <b>${escapeHtml(r.list_name)}</b> ${r.folder_name ? `(${escapeHtml(r.folder_name)})` : ''}\n   ID: ${r.list_id} | Thêm bởi: ${escapeHtml(r.added_by)} lúc ${addedDate}`);
});

return [{ json: { chatId, text: lines.join('\n'), parse_mode: 'HTML' } }];

const chatId = $('Phân tích lệnh').first().json.chatId;
const rows = $input.all().map(i => i.json).filter(r => r && r.list_name);
const escapeHtml = (t) => (t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

if (rows.length === 0) {
  return [{ json: { chatId, text: '📊 Postgres hiện chưa có dữ liệu task nào.', parse_mode: 'HTML' } }];
}

const statusEmoji = (status) => {
  const s = (status || '').toLowerCase();
  if (s.includes('xử lý') || s.includes('xu ly')) return '⚙️';
  if (s.includes('ready') || s.includes('sẵn sàng')) return '✅';
  if (s.includes('lỗi') || s.includes('loi')) return '❌';
  if (s.includes('chờ') || s.includes('cho')) return '⏳';
  return '🔹';
};

const byList = {};
for (const r of rows) {
  if (!byList[r.list_name]) byList[r.list_name] = [];
  byList[r.list_name].push(r);
}

const lines = ['📊 <b>Thống kê dữ liệu hiện có trong Postgres:</b>\n'];
let grandTotal = 0;
for (const [listName, statuses] of Object.entries(byList)) {
  const listTotal = statuses.reduce((sum, r) => sum + r.cnt, 0);
  grandTotal += listTotal;
  lines.push(`📋 <b>${escapeHtml(listName)}</b>: ${listTotal} task`);
  statuses.forEach(r => { lines.push(`   ${statusEmoji(r.status)} ${escapeHtml(r.status) || 'Không rõ'}: ${r.cnt}`); });
  lines.push('');
}
lines.push(`━━━━━━━━━━\n<b>Tổng cộng: ${grandTotal} task</b>`);

return [{ json: { chatId, text: lines.join('\n'), parse_mode: 'HTML' } }];

// Dieu 'sub workflow' (Execute Workflow Trigger) cua ban goc nhan du lieu shape Envelope da co san
// tu Gateway. Bot System nay dung TRUC TIEP (khong qua Gateway) nen phai tu build Envelope tuong tu
// tu raw Telegram Trigger output.
const items = $input.all();
return items.map(it => {
  const upd = it.json;
  const isCallback = !!upd.callback_query;
  const msg = isCallback ? upd.callback_query.message : upd.message;
  const text = isCallback ? (upd.callback_query.data || '') : (msg?.text || '');

  return {
    json: {
      request_id: `sysbot_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      platform: 'telegram',
      kind: isCallback ? 'callback' : 'message',
      user_id: isCallback ? upd.callback_query.from.id : msg?.from?.id,
      username: isCallback ? upd.callback_query.from.username : msg?.from?.username,
      chat_id: msg?.chat?.id,
      text: isCallback ? undefined : text,
      callback: isCallback ? { id: upd.callback_query.id, data: text, message_id: msg?.message_id } : undefined,
      raw: upd,
    }
  };
});
